INSERT INTO supplier_options(name,region,website,product_categories,published_terms,costs_confirmed,status) VALUES
('MP DROP','Brasil','https://mpdrop.app/','Casa e organização: confirmar no catálogo autenticado; priorizar kits leves e não frágeis.','Acesso sem mensalidade informado para cadastros até 31/12/2026; pagamento do custo por pedido via Pix; plataforma informa NF-e e rastreio. Confirmar SKU, frete, estoque e política de devolução antes de selecionar.',false,'needs_verification'),
('Dropnacional via Dropi','Brasil','https://dropnacional.com.br/','Catálogo nacional amplo; filtrar por casa e organização após login.','Teste informado de 3 dias; plano profissional anunciado a partir de R$ 89/mês depois do teste. Produto e frete pagos por pedido; notas fiscais e envio direto anunciados.',false,'needs_verification'),
('CJdropshipping','Internacional','https://cjdropshipping.com/','Organização compacta, acessórios de cozinha e armazenamento; preferir armazém próximo ao Brasil se disponível.','Plano básico anunciado a US$ 0/mês; cada pedido cobra produto e logística. Cotar frete, prazo e impostos para o CEP do cliente; estoque e qualidade variam por SKU.',false,'needs_verification'),
('AliExpress — fornecedor individual','Internacional','https://www.aliexpress.com/','Organizadores leves; apenas vendedores que confirmem por escrito dropshipping sem material promocional e rastreamento.','Não tratar marketplace como garantia de dropshipping: vendedor, custo, prazo, importação e devoluções devem ser verificados individualmente. Não conectar automaticamente sem credenciais e testes.',false,'needs_verification')
INSERT INTO supplier_candidates(slug,product_name,category,reference_price_cents,reference_merchant,reference_note,national_supplier,international_supplier,risk_level,status,target_margin_pct) VALUES
('kit-colmeia-gavetas','Kit colmeia organizadora de gavetas','Quarto e closet',3894,'Amazon.com.br / Mercado Livre','Market reference checked 19/10/2026: Amazon listing R$ 38,94 with 4.9/5 and 177 reviews; Mercado Livre Casa e Ordem also showed comparable colmeias around R$ 32 and listings with 100+ sales. Signals are not a guarantee of demand for the exact supplier SKU. https://www.mercadolivre.com.br/loja/casa-e-ordem','MP DROP — confirmar se há SKU equivalente','CJdropshipping — cotar SKU equivalente e frete ao Brasil','low','candidate',20),
('kit-caixas-dobraveis','Kit com 3 caixas organizadoras dobráveis','Quarto e armazenamento',4455,'Amazon.com.br','Market reference checked 19/10/2026: comparable 3-piece foldable organizer set around R$ 44,55; exact size/material and freight must match. https://www.amazon.com.br/','MP DROP — confirmar kit e medidas','CJdropshipping — comparar custo dimensional e frete','medium','candidate',20),
('kit-sacos-vacuo','Kit de sacos a vácuo com bomba','Quarto e closet',4399,'Shopee','Market reference checked 19/10/2026: 4-piece vacuum bag kit with manual pump around R$ 43,99. Test sealing and valve durability; this is not supplier cost. https://shopee.com.br/','MP DROP — confirmar bomba, válvula e política de defeito','CJdropshipping — solicitar inspeção de válvula e vedação','medium','candidate',20),
('sapateira-compacta','Sapateira compacta de porta ou empilhável','Quarto e closet',2999,'Vale Muito Isso','Referência varejista aproximada publicada em 2026; variantes não são equivalentes. Link: https://valemuitoisso.com.br/categoria/organizacao','MP DROP — confirmar dimensões e montagem','CJdropshipping — preferir produto leve/desmontável','medium','candidate',20),
('porta-ovos-geladeira','Porta-ovos organizador de geladeira','Cozinha',1399,'Maravilhas do Lar','Market reference checked 19/10/2026: 4-tier egg organizer around R$ 13,99, listing showed 4.8/5 and 265 reviews. Verify capacity and material for food contact. https://www.maravilhasdolar.com.br/','MP DROP — confirmar material e capacidade','CJdropshipping — cotar apenas plástico para contato alimentar com documentação','medium','candidate',20),
('prateleira-ventosa','Prateleira organizadora com ventosa','Banheiro e cozinha',3735,'Shopee','Market reference checked 19/10/2026: similar suction-cup shelf around R$ 37,35, listing showed 5.0/5 but only 1 review. High failure/return risk; load and surface tests required. https://shopee.com.br/','MP DROP — confirmar superfície compatível e reclamações','CJdropshipping — testar carga e superfícies antes de aprovar','high','candidate',20),
('separador-talheres','Organizador modular de gaveta (divisórias)','Cozinha',1899,'OU','Market reference checked 19/10/2026: comparable modular drawer organizer around R$ 18,99 with 4.5/5 and 30 reviews. Confirm exact number of dividers and dimensions. https://www.ou.com.br/','MP DROP — buscar SKU e material equivalente','CJdropshipping — comparar dimensões e frete volumétrico','low','candidate',20),
('organizador-geladeira-42l','Organizador de geladeira ventilável 4,2 L','Cozinha',2249,'Shopee','Market reference checked 19/10/2026: 4 L refrigerator organizer around R$ 22,49, listing showed 4.8/5 and 553 reviews. Confirm exact dimensions, ventilation and material. https://shopee.com.br/','MP DROP — confirmar SKU equivalente','CJdropshipping — frete pode tornar item barato inviável','medium','candidate',20),
('caixa-empilhavel-14l','Caixa organizadora empilhável 14 L','Quarto e armazenamento',3899,'Dipratos / Pleion','Market reference checked 19/10/2026: Pleion Bioprátika box with lid around R$ 38,99; compare volume, lid and dimensions before treating it as equivalent. Volumetric freight may erase margin. https://www.dipratos.com.br/','MP DROP — confirmar volume, tampa e envio','CJdropshipping — cotar peso dimensional antes de considerar','high','candidate',20),
('organizador-modular-gaveta','Kit de organizadores modulares de gaveta (4 peças)','Quarto e closet',4157,'Shopee','Market reference checked 19/10/2026: modular acrylic drawer organizer kit around R$ 41,57 with 4.9/5 and 588 reviews. Verify the exact kit/number of pieces; rating and price refer to a comparable listing, not the future supplier SKU. https://shopee.com.br/','MP DROP — confirmar fabricante, medidas e acabamento','CJdropshipping — cotar SKU exato ou equivalente','low','candidate',20)
